def color_comps(grid,bg,top_end):
 ret=[];h=len(grid);w=len(grid[0])
 for color in sorted({grid[r][c] for r in range(top_end) for c in range(w)}-{bg}):
  seen=set()
  for r in range(top_end):
   for c in range(w):
    if grid[r][c]!=color or (r,c) in seen:continue
    q=[(r,c)];seen.add((r,c));cells=[]
    while q:
     y,x=q.pop();cells.append((y,x))
     for yy,xx in [(y-1,x),(y+1,x),(y,x-1),(y,x+1)]:
      if 0<=yy<top_end and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
       seen.add((yy,xx));q.append((yy,xx))
    ret.append((color,cells))
 return ret
